import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.wVcpyw2-.js";const u=JSON.parse('{"title":"我的模块","description":"查看灵萌站点已开通与未解锁功能模块，更新授权文件，排查侧栏菜单不显示。","frontmatter":{"title":"我的模块","description":"查看灵萌站点已开通与未解锁功能模块，更新授权文件，排查侧栏菜单不显示。"},"headers":[],"relativePath":"config/my-modules.md","filePath":"config/my-modules.md","lastUpdated":1785020677000}'),o={name:"config/my-modules.md"};function i(l,t,n,h,s,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="我的模块" tabindex="-1">我的模块 <a class="header-anchor" href="#我的模块" aria-label="Permalink to &quot;我的模块&quot;">​</a></h1><p>路径：<strong>系统设置 → 我的模块</strong></p><p>查看当前站点<strong>已开通</strong>与<strong>未解锁</strong>的功能模块，以及授权状态、到期时间。侧栏菜单是否出现，首先看这里是否已开通。</p><hr><h2 id="什么时候来这页" tabindex="-1">什么时候来这页 <a class="header-anchor" href="#什么时候来这页" aria-label="Permalink to &quot;什么时候来这页&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>做什么</th></tr></thead><tbody><tr><td>刚部署完</td><td>核对商务承诺的模块是否都显示为「已开通」</td></tr><tr><td>侧栏没有外卖 / AI / 私信等</td><td>先看是否在「未解锁」里</td></tr><tr><td>授权续期或加购模块后</td><td>点 <strong>更新授权文件</strong>，再 <strong>刷新</strong></td></tr></tbody></table><hr><h2 id="页面怎么看" tabindex="-1">页面怎么看 <a class="header-anchor" href="#页面怎么看" aria-label="Permalink to &quot;页面怎么看&quot;">​</a></h2><p>顶部汇总大致包括：</p><table tabindex="0"><thead><tr><th>信息</th><th>含义</th></tr></thead><tbody><tr><td>授权状态</td><td>当前授权是否有效</td></tr><tr><td>已开通 / 未解锁</td><td>模块数量</td></tr><tr><td>客户 / 到期 / 最大版本</td><td>授权归属与有效期</td></tr></tbody></table><p>下方分两块：</p><ul><li><strong>已开通模块</strong> — 侧栏对应功能一般可用（仍可能受账号权限限制）</li><li><strong>未解锁模块</strong> — 需联系商务开通或更新授权</li></ul><p>可用分类筛选：全部 / 基础内置 / 消息通讯 / 社区互动 / 交易营销 / 本地生活 / 基础设施 / 运营智能化。</p><hr><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><h3 id="查看模块" tabindex="-1">查看模块 <a class="header-anchor" href="#查看模块" aria-label="Permalink to &quot;查看模块&quot;">​</a></h3><ol><li>打开 <strong>系统设置 → 我的模块</strong></li><li>用分类 pill 筛选你关心的模块</li><li>对照侧栏：已开通但仍看不到菜单 → 再查 <a href="/config/admin-permissions">账号权限</a></li></ol><h3 id="更新授权文件" tabindex="-1">更新授权文件 <a class="header-anchor" href="#更新授权文件" aria-label="Permalink to &quot;更新授权文件&quot;">​</a></h3><p>加购或续期后：</p><ol><li>点 <strong>更新授权文件</strong></li><li>确认提示：「将从授权站拉取当前站点的最新授权文件并部署到本地」</li><li>成功后点 <strong>刷新</strong>，确认新模块进入「已开通」</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>请确认服务器能访问授权站，且站点授权编号/密钥正确。失败时页面会提示原因；也可联系交付方协助。</p></div><hr><h2 id="与「内测中」的区别" tabindex="-1">与「内测中」的区别 <a class="header-anchor" href="#与「内测中」的区别" aria-label="Permalink to &quot;与「内测中」的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>显示</th><th>含义</th></tr></thead><tbody><tr><td><strong>未解锁</strong>（我的模块）</td><td>授权未包含该能力</td></tr><tr><td>侧栏「内测中」</td><td>产品功能尚未对全部站点开放（如部分商户管理入口），即使授权也可能暂时无法进入</td></tr><tr><td>菜单灰色 / 无权限</td><td>模块已开，但当前账号未分配 <a href="/config/admin-permissions">账号权限</a></td></tr></tbody></table><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>空态提示检查授权文件</td><td>初始化向导或授权步骤未完成；联系交付方配置 license</td></tr><tr><td>更新授权后仍未解锁</td><td>刷新页面；确认加购模块已写入授权站；核对站点标识是否正确</td></tr><tr><td>已开通但侧栏没有</td><td>用超管登录对比；给当前账号分配对应菜单权限</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/guide/admin-access">进入管理后台</a></li><li><a href="/config/admin-permissions">账号权限与权限模板</a></li><li><a href="/guide/modules">功能模块总览</a></li></ul>',30)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
